import copy


class StateMachine:
    def __init__(self, transitions, initial_state, *, guards=None, actions=None):
        self._transitions = dict(copy.deepcopy(transitions))
        self._guards = dict(copy.deepcopy(guards)) if guards is not None else {}
        self._actions = dict(copy.deepcopy(actions)) if actions is not None else {}
        self._state = initial_state
        self._in_callback = False

    def current(self):
        return self._state

    def can_trigger(self, event):
        return (self._state, event) in self._transitions

    def trigger(self, event, **payload):
        key = (self._state, event)
        if key not in self._transitions:
            raise ValueError(
                "no transition defined for state %r on event %r" % (self._state, event)
            )
        if self._in_callback:
            raise RuntimeError("nested trigger on the same StateMachine instance")
        new_state = self._transitions[key]
        guard = self._guards.get(key)
        if guard is not None:
            self._in_callback = True
            try:
                ok = guard(self._state, event, dict(payload))
            finally:
                self._in_callback = False
            if not ok:
                raise ValueError(
                    "guard rejected transition for state %r on event %r"
                    % (self._state, event)
                )
        action = self._actions.get(key)
        if action is not None:
            self._in_callback = True
            try:
                action(self._state, new_state, event, dict(payload))
            finally:
                self._in_callback = False
        self._state = new_state
        return self._state
